    vx_p, vy_p = sandbox.get_agent_velocity()
    state["vx"], state["vy"] = vx_p, vy_p
    front, up, down = sandbox.get_whisker_readings()

    if state["phase"] == "APPROACH":
        # Move forward, avoiding walls
        if front < 1.5:
            # Wall ahead, turn left
            fx = -30.0  # Leftward force
        elif front > 3.0:
            # No wall ahead, move forward
            fx = 50.0
        else:
            # Moderate distance, move forward
            fx = 50.0

        # Adjust vertical force based on floor/ceiling proximity
        if down < 1.0:
            # Near floor, lift up
            fy = 50.0 * (1.5 - y) - 20.0 * state["vy"] + _weight_comp(sandbox)
        elif up < 1.0:
            # Near ceiling, lower
            fy = -50.0 * (1.5 - y) - 20.0 * state["vy"] + _weight_comp(sandbox)
        else:
            # No floor/ceiling wall, maintain vertical position
            fy = 50.0 * (1.5 - y) - 20.0 * state["vy"] + _weight_comp(sandbox)

        # Check if in activation zone
        if cfg["act_lo"] <= x <= cfg["act_hi"] and abs(state["vx"]) < 0.5:
            state["phase"] = "UNLOCK"
            state["t"] = 0

    elif state["phase"] == "UNLOCK":
        spd = math.hypot(state["vx"], state["vy"])
        fx_cmd = cfg["bfx"] - 1.0  # Ensure commanded force is below threshold
        fy_cmd = 50.0 * (1.5 - y) - 20.0 * state["vy"] + _weight_comp(sandbox)

        # Adjust force based on speed
        if spd >= cfg["bspd"] * 0.99:
            horiz = -1.5 * state["vx"]
            if horiz > 0:
                horiz = 0
            fx_cmd += horiz
            fy_cmd -= 1.5 * state["vy"]

        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1
        if state["t"] > 60:
            state["phase"] = "ESCAPE"

    elif state["phase"] == "ESCAPE":
        fx = 15.0
        fy = 50.0 * (1.5 - y) - 20.0 * state["vy"] + _weight_comp(sandbox)
        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"

    elif state["phase"] == "HOLD":
        fx, fy = 0.0, _weight_comp(sandbox)

    # Apply force, clamped to prevent excessive impulse
    fx = max(-MAX_FORCE, min(MAX_FORCE, fx))
    fy = max(-MAX_FORCE, min(MAX_FORCE, fy))
    sandbox.apply_agent_force(fx, fy)

